"""
Pydantic schemas for Gemini AI classification.
Used for structured output validation, JSON parsing, and confidence scoring.
"""

from typing import Optional, List
from pydantic import BaseModel, Field


class AIClassificationResult(BaseModel):
    """Structured classification output generated by Gemini API."""

    slow_network_report: bool = Field(
        default=False,
        description="True ONLY if customer explicitly reports slow network / lag / disconnection. False if staff is just asking about network."
    )
    device_name: Optional[str] = Field(
        default=None,
        description="Extracted device/machine name (e.g. 'PC-04', 'May 12', 'Cloud-01'). None if not mentioned."
    )
    device_tested: bool = Field(
        default=False,
        description="True ONLY if customer confirmed they have ALREADY tested the device. False if customer only says they will test later."
    )
    feedback_received: bool = Field(
        default=False,
        description="True ONLY if customer has actually replied with their feedback or test experience. False if staff merely requested feedback."
    )
    positive_feedback: bool = Field(
        default=False,
        description="True if customer feedback was positive (e.g. fast, smooth, good, satisfied)."
    )
    ticket_opened: bool = Field(
        default=False,
        description="True if a new ticket / issue was initiated in this interaction."
    )
    ticket_closed: bool = Field(
        default=False,
        description="True if the ticket / issue was marked resolved or closed."
    )
    escalated: bool = Field(
        default=False,
        description="True ONLY if case was actually escalated/transferred to a senior (Duong or Tung). False if their names were just mentioned in passing."
    )
    escalation_owner: Optional[str] = Field(
        default=None,
        description="Must be 'Dương' or 'Tùng' if escalated. None otherwise."
    )
    escalation_reason: Optional[str] = Field(
        default=None,
        description="Short concise reason for escalation. None if not escalated."
    )
    needs_follow_up: bool = Field(
        default=False,
        description="True if customer needs further follow up later."
    )
    follow_up_action: Optional[str] = Field(
        default=None,
        description="Concise description of what needs to be followed up."
    )
    pending_case: bool = Field(
        default=False,
        description="True if case is still pending unresolved."
    )
    pending_reason: Optional[str] = Field(
        default=None,
        description="Short concise description of pending status."
    )
    needs_manager_review: bool = Field(
        default=False,
        description="True if issue requires manager (anh Tùng) review."
    )
    manager_review_desc: Optional[str] = Field(
        default=None,
        description="Concise description of the problem for manager review."
    )
    evidence_message_ids: List[str] = Field(
        default_factory=list,
        description="List of message IDs that provide concrete evidence for these labels."
    )
    needs_manual_review: bool = Field(
        default=False,
        description="True if interaction is ambiguous, missing context, or confidence is low."
    )
    confidence: float = Field(
        default=1.0,
        ge=0.0,
        le=1.0,
        description="Confidence score between 0.0 and 1.0."
    )


class SanitizedConversationInput(BaseModel):
    """Input representation of conversation messages sent to Gemini after PII scrubbing."""
    conversation_id: str
    messages: List[dict] # [{"id": "...", "role": "customer"|"staff", "text": "..."}]
